func (r *named) Search(ctx context.Context, o SearchOpts) ([]model.Video, error) {
	v, err := r.Reader.Search(ctx, o)
	r.done(ctx, "Search", err)
	return v, err
}

func (f *fallback) Search(ctx context.Context, o SearchOpts) ([]model.Video, error) {
	return call(ctx, f, func(r Reader) ([]model.Video, error) { return r.Search(ctx, o) })
}

func (c *cached) Search(ctx context.Context, o SearchOpts) ([]model.Video, error) {
	return cachedCall(ctx, "Search", []any{o}, func(ctx context.Context) ([]model.Video, error) { return c.Reader.Search(ctx, o) })
}

